package android.media; public class MediaMetadata {static String repeat(String s,int n){StringBuilder b=new StringBuilder();for(int i=0;i<n;i++)b.append(s);return b.toString();} public String getString(String key){String s=System.getProperty("scenario");if(s.equals("total-oversize"))return repeat("x",8192);if(key.equals("android.media.metadata.TITLE")){if(s.equals("oversized"))return repeat("x",8193);if(s.equals("utf8-oversized"))return repeat("界",3000);if(s.equals("boundary"))return repeat("x",8192);if(s.equals("unicode"))return "A \"quote\" \\ newline\n界 \ud83d\ude00 \u0001";if(s.equals("credentials"))return "A normal title: https://example.test/watch?v=abc and Authorization: Bearer abcSecret.123 password=private123 finish";if(s.equals("auth-url"))return "Visit https://bob:private123@example.test/view?access_token=private456&v=abc#part and https://example.test/about";if(s.equals("ordinary"))return "Bearer bonds Password stories https://example.test/watch?v=abc&key=ordinary bob@example.test";if(s.equals("encoded-query"))return "https://example.test/view?access%5Ftoken=private123&v=abc";if(s.equals("quoted-secret"))return "hello password=\"has spaces secret\" goodbye";if(s.equals("unpaired-surrogate"))return "\ud800";if(s.equals("short-bearer"))return "Authorization: Bearer abc end";if(s.equals("url-fragment"))return "https://example.test/view?token=private123#chapter";if(s.equals("username-url"))return "https://bob@example.test/view";if(s.equals("ordinary-prose"))return "Bearer of good news and token economics";if(s.equals("redaction-expansion"))return repeat("token=a ",1024);if(s.equals("standalone-bearer"))return "bearer abcSecret.123 after";return "Synthetic title";}if(key.equals("android.media.metadata.MEDIA_ID")&&s.equals("media-id"))return "https://example.test/title?id=abc";return null;}public boolean containsKey(String key){if(!key.equals("android.media.metadata.DURATION"))throw new AssertionError("unselected key");String s=System.getProperty("scenario");return s.equals("duration")||s.equals("bad-duration")||s.equals("unsafe-duration");}public long getLong(String key){String s=System.getProperty("scenario");return s.equals("bad-duration")?-1:s.equals("unsafe-duration")?9007199254740992L:0;}}
